            C++

    #include <iostream>
using namespace std;

// Node class
class Node {
public:
    int data;
    Node* next;
    Node(int new_data) {
        data = new_data;
        next = nullptr;
    }
};

// Queue class
class myQueue {
private:
    int currSize;
    Node* front;
    Node* rear;

public:
    myQueue() {
        currSize = 0;
        front = rear= nullptr;
    }

    // Check if empty
    bool isEmpty() {
        return front == nullptr;
    }

    // Enqueue
    void enqueue(int new_data) {
        Node* node = new Node(new_data);
        if (isEmpty()) {
            front = rear = node;
        } else {
            rear->next = node;
            rear = node;
        }

        currSize++;
    }

    // Dequeue
    int dequeue() {
        if (isEmpty()) {
            cout << "Queue Underflow" << endl;
            return -1;
        }

        Node* temp = front;
        int removedData = temp->data;
        front = front->next;

        if (front == nullptr) rear = nullptr;
        delete temp;

        currSize--;
        return removedData;
    }

    // Get front element
    int getfront() {
        if (isEmpty()) {
            cout << "Queue is empty" << endl;
            return -1;
        }
        return front->data;
    }

    // Get size
    int size() {
       return currSize;
    }
};

int main() {
    myQueue q;

    q.enqueue(10);
    q.enqueue(20);

    cout << q.dequeue() << "\n";

    q.enqueue(30);


    cout << q.getfront() << endl;
    cout <<  q.size() << endl;

    return 0;
}


            C

    #include <stdio.h>
#include <stdlib.h>

// Node structure
typedef struct Node {
    int data;
    struct Node* next;
} Node;

// myQueue structure
typedef struct myQueue {
    int currSize;
    Node* front;
    Node* rear;
} myQueue;

// Create a new node
Node* newNode(int data) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->next = NULL;
    return node;
}

// Create an empty queue
myQueue* createQueue() {
    myQueue* q = (myQueue*)malloc(sizeof(myQueue));
    q->front = q->rear = NULL;
    q->currSize = 0;
    return q;
}

// Check if the queue is empty
int isEmpty(myQueue* q) {
    return q->front == NULL;
}

// Enqueue operation
void enqueue(myQueue* q, int data) {
    Node* node = newNode(data);
    if (isEmpty(q)) {
        q->front = q->rear = node;
    } else {
        q->rear->next = node;
        q->rear = node;
    }

    q->currSize++;
}

// Dequeue operation
int dequeue(myQueue* q) {
    if (isEmpty(q)) {
        printf("Queue Underflow\n");
        return -1;
    }

    Node* temp = q->front;
    int removedData = temp->data;
    q->front = q->front->next;
    if (q->front == NULL) q->rear = NULL;
    free(temp);

    q->currSize--;
    return removedData;
}

// Get front element
int getFront(myQueue* q) {
    if (isEmpty(q)) {
        printf("Queue is empty\n");
        return -1;
    }
    return q->front->data;
}

// Get queue size
int size(myQueue* q) {
    return q->currSize;
}

int main() {
    myQueue* q = createQueue();

    enqueue(q, 10);
    enqueue(q, 20);

    printf("%d\n",dequeue(q));

    enqueue(q, 30);

    printf("%d\n", getFront(q));
    printf("%d\n", size(q));

    return 0;
}


